@section('content')
@php
$adminName = $currentAdmin->name ?? 'Admin';
$periodLabels=['1d'=>'Last 24 hours','7d'=>'Last 7 days','30d'=>'Last 30 days','all'=>'All time'];
$trend=$dashboard['bookingTrend'] ?? collect();
$maxRev=max(1,(float)$trend->max('revenue')); $maxBookings=max(1,(int)$trend->max('bookings'));
$points=[];$points2=[];$n=max(1,$trend->count()-1);
foreach($trend as $i=>$r){$x=($i/$n)*100;$points[]=round($x,2).','.round(84-((float)$r['revenue']/$maxRev)*68,2);$points2[]=round($x,2).','.round(84-((int)$r['bookings']/$maxBookings)*68,2);}
$revPoly=implode(' ',$points);$bookPoly=implode(' ',$points2);
$mix=$dashboard['productMix'] ?? [];$mixTotal=max(1,array_sum($mix));
$mixColors=['#2563eb','#7c3aed','#11a36a','#f59e0b','#e83c68'];$deg=0;$grad=[];$idx=0;
foreach($mix as $label=>$val){$next=$deg+(((int)$val/$mixTotal)*360);$grad[]=$mixColors[$idx%count($mixColors)].' '.$deg.'deg '.$next.'deg';$deg=$next;$idx++;}
$mixGradient=implode(',',$grad);
$funnel=$dashboard['leadFunnel'] ?? ['total'=>0,'active'=>0,'response'=>0,'hot'=>0,'converted'=>0];
$payments=$dashboard['paymentMethods'] ?? collect();$payTotal=max(1,(int)$payments->sum());
$statusTone=function($s){return in_array($s,['Refunded','Cancelled'])?'red':(in_array($s,['Ticketed','Issued','Confirmed'])?'green':(in_array($s,['Fresh','New Booking'])?'blue':'slate'));};
@endphp
